<?php require_once '../includes/auth.php';login_required();$s=store();if(!$s)go('/seller/store.php');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);$cat=trim($_POST['category']??'');$img=null;if(!$name||$price===false||$price<0||!$cat)$error='Name, valid price and category are required.';if(!$error&&!empty($_FILES['image']['name'])){$f=$_FILES['image'];$m=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($f['error']||$f['size']>2097152||!isset($ok[$m]))$error='Image must be JPG, PNG or WebP under 2MB.';else{$img=bin2hex(random_bytes(12)).'.'.$ok[$m];move_uploaded_file($f['tmp_name'],'../uploads/'.$img);}}if(!$error){$q=$pdo->prepare('INSERT INTO products(store_id,name,description,price,category,image,variations,available)VALUES(?,?,?,?,?,?,?,?)');$q->execute([$s['id'],$name,trim($_POST['description']??''),$price,$cat,$img,trim($_POST['variations']??''),isset($_POST['available'])?1:0]);go('/seller/products.php');}}$title='Add product';require '../includes/header.php';?><h1>Add product</h1><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card card-body col-lg-8"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="form-control mb-2" name="name" placeholder="Name" required><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><input class="form-control mb-2" type="number" step="0.01" min="0" name="price" placeholder="Price in naira" required><input class="form-control mb-2" name="category" placeholder="Category" required><input class="form-control mb-2" name="variations" placeholder="Variations e.g. Small, Medium, Large"><input class="form-control mb-2" type="file" name="image" accept="image/jpeg,image/png,image/webp"><label><input type="checkbox" name="available" checked> Available</label><button class="btn btn-success mt-3">Save</button></form><?php require '../includes/footer.php';?>